#[test]
fn genai_attach_agent_function_genai_attach_agent_function_401_decodes_declared_error() {
    let Some(config) = configured_client() else {
        return;
    };
    let config = ClientConfig {
        base_url: config
            .base_url
            .map(|base_url| format!("{base_url}/__mockStatus/401")),
        ..config
    };
    let result = agent_platform_api::genai_attach_agent_function(
        &config,
        agent_platform_api::GenaiAttachAgentFunctionParams {
            agent_uuid: decode(fixture(r#""\"123e4567-e89b-12d3-a456-426614174000\"""#)),
            agent_uuid_2: Some(decode(fixture(
                r#""\"12345678-1234-1234-1234-123456789012\"""#,
            ))),
            description: Some(decode(fixture(r#""\"My Function Description\"""#))),
            faas_name: Some(decode(fixture(r#""\"my-function\"""#))),
            faas_namespace: Some(decode(fixture(r#""\"default\"""#))),
            function_name: Some(decode(fixture(r#""\"My Function\"""#))),
            input_schema: Some(decode(fixture(r#"{}"#))),
            output_schema: Some(decode(fixture(r#"{}"#))),
        },
        None,
    );
    let Err(::octridev_digitalocean::errors::SdkError::Http(error)) = result else {
        panic!("genai_attach_agent_function did not fail with SdkError::Http on 401");
    };
    assert_eq!(error.status_code, 401);
    let actual = serde_json::to_value(&error.data).expect("serialize declared error body");
    let expected = fixture(r#"{"id":"unauthorized","message":"Unable to authenticate you."}"#);
    assert!(
        representative(&actual, &expected),
        "genai_attach_agent_function decoded error body {actual}, expected representative {expected}"
    );
}

