#[test]
fn genai_create_agent_genai_create_agent_401_decodes_declared_error() {
    let Some(config) = configured_client() else {
        return;
    };
    let config = ClientConfig {
        base_url: config
            .base_url
            .map(|base_url| format!("{base_url}/__mockStatus/401")),
        ..config
    };
    let result = agent_platform_api::genai_create_agent(
        &config,
        agent_platform_api::GenaiCreateAgentParams {
            anthropic_key_uuid: Some(decode(fixture(
                r#""\"12345678-1234-1234-1234-123456789012\"""#,
            ))),
            description: Some(decode(fixture(r#""\"My Agent Description\"""#))),
            instruction: Some(decode(fixture(
                r#""\"You are an agent who thinks deeply about the world\"""#,
            ))),
            knowledge_base_uuid: Some(decode(fixture(r#"["example string"]"#))),
            mcp_servers: Some(decode(fixture(
                r#"[{"allowed_tools":["example string"],"authorization":"example string","headers":{"key":"example string"},"server_label":"example string","server_url":"example string"}]"#,
            ))),
            model_provider_key_uuid: Some(decode(fixture(
                r#""\"12345678-1234-1234-1234-123456789012\"""#,
            ))),
            model_router_uuid: Some(decode(fixture(
                r#""\"12345678-1234-1234-1234-123456789012\"""#,
            ))),
            model_uuid: Some(decode(fixture(
                r#""\"12345678-1234-1234-1234-123456789012\"""#,
            ))),
            name: Some(decode(fixture(r#""\"My Agent\"""#))),
            open_ai_key_uuid: Some(decode(fixture(
                r#""\"12345678-1234-1234-1234-123456789012\"""#,
            ))),
            project_id: Some(decode(fixture(
                r#""\"12345678-1234-1234-1234-123456789012\"""#,
            ))),
            reasoning_effort: Some(decode(fixture(r#""\"low\"""#))),
            region: Some(decode(fixture(r#""\"tor1\"""#))),
            router_preset_slug: Some(decode(fixture(r#""\"general\"""#))),
            tags: Some(decode(fixture(r#"["example string"]"#))),
            thinking_token_budget: Some(decode(fixture(r#"123"#))),
            web_fetch_enabled: Some(decode(fixture(r#"true"#))),
            web_search_enabled: Some(decode(fixture(r#"true"#))),
            workspace_uuid: Some(decode(fixture(r#""123e4567-e89b-12d3-a456-426614174000""#))),
        },
        None,
    );
    let Err(::octridev_digitalocean::errors::SdkError::Http(error)) = result else {
        panic!("genai_create_agent did not fail with SdkError::Http on 401");
    };
    assert_eq!(error.status_code, 401);
    let actual = serde_json::to_value(&error.data).expect("serialize declared error body");
    let expected = fixture(r#"{"id":"unauthorized","message":"Unable to authenticate you."}"#);
    assert!(
        representative(&actual, &expected),
        "genai_create_agent decoded error body {actual}, expected representative {expected}"
    );
}

