#[test]
fn genai_get_workspace_genai_get_workspace_401_decodes_declared_error() {
    let Some(config) = configured_client() else {
        return;
    };
    let config = ClientConfig {
        base_url: config
            .base_url
            .map(|base_url| format!("{base_url}/__mockStatus/401")),
        ..config
    };
    let result = agent_platform_api::genai_get_workspace(
        &config,
        agent_platform_api::GenaiGetWorkspaceParams {
            workspace_uuid: decode(fixture(r#""\"123e4567-e89b-12d3-a456-426614174000\"""#)),
        },
        None,
    );
    let Err(::octridev_digitalocean::errors::SdkError::Http(error)) = result else {
        panic!("genai_get_workspace did not fail with SdkError::Http on 401");
    };
    assert_eq!(error.status_code, 401);
    let actual = serde_json::to_value(&error.data).expect("serialize declared error body");
    let expected = fixture(r#"{"id":"unauthorized","message":"Unable to authenticate you."}"#);
    assert!(
        representative(&actual, &expected),
        "genai_get_workspace decoded error body {actual}, expected representative {expected}"
    );
}

